{
 "mode": "filter",
 "query": "invoice retention purge delete",
 "include_invalidated": true
}

{
 "command": "git ls-files && cat README* 2>/dev/null | head -50",
 "description": "List repo files and README"
}

{
 "command": "cat migrations/*.sql scripts/backfill_tax.py scripts/export.py src/billing/refunds.py docs/ops/backfills.md; grep -n -i -A3 \"retention\\|purge\\|connect\\|structlog\" docs/runbook.md src/*.py src/billing/invoices.py pyproject.toml | head -60",
 "description": "Read schema, scripts and refund code"
}

{
 "command": "cat tests/test_db.py src/billing/invoices.py docker-compose.yml; grep -rn \"finalized_at\\|status\\|psycopg\\|DATABASE_URL\" --include=*.py --include=*.md --include=*.toml . | grep -v .engramdb | head -30; cat .engramdb/memories/use-structlog* .engramdb/memories/large-refunds*",
 "description": "Inspect DB usage and conventions"
}

{
 "command": "python -m py_compile scripts/purge_invoices.py && python scripts/purge_invoices.py; echo rc=$?; python scripts/purge_invoices.py --batch-size 2000; echo rc=$?; python -c \"\nimport sys; sys.path.insert(0,'scripts'); import purge_invoices as p\nfrom datetime import datetime,timezone; print(p.cutoff_utc(datetime(2026,10,2,tzinfo=timezone.utc)))\"",
 "description": "Compile and smoke-test the script"
}
